// A Buildertrend bills export as CSV, with the column names set in Config (field_*). Run "Test workflow" to see the report.
const d = n => new Date(Date.now() - n * 864e5).toISOString().slice(0, 10);   // dates relative to today, so the sample never ages out
const csv = [
  'Job,Sub/Vendor,Bill #,Date,Amount',
  `"Maple St Remodel",Acme Lumber,AL-5521,${d(20)},"4,812.40"`,
  `"Maple St Remodel",Brightline Electric,BE-118,${d(17)},2950.00`,
  `"Oak Ave Addition",Acme Lumber,AL-5530,${d(15)},1180.00`,
  `"Oak Ave Addition",Precision Plumbing,PP-77,${d(13)},1625.00`,
  `"Oak Ave Addition",Stone & Tile Co,ST-904,${d(10)},880.00`,
  `"Hill Rd Deck",Acme Lumber,AL-5544,${d(8)},2210.75`,
].join('\n');
return [{ json: { csv, export_name: 'sample-bills.csv', export_time: new Date().toISOString() } }];

// Reads the CSV (quoted fields, commas inside quotes, "1,234.50" amounts). Column names come from Config, so match them to your export.
const cfg = $('Config').first().json, src = $input.first().json;
const text = String(src.csv ?? src.data ?? '');
const rows = [], re = /("([^"]|"")*"|[^,\n\r]*)(,|\r?\n|$)/g;
let row = [], m;
while ((m = re.exec(text)) && m[0] !== '') {
  let v = m[1]; if (v.startsWith('"')) v = v.slice(1, -1).replace(/""/g, '"');
  row.push(v.trim()); if (m[3] !== ',') { if (row.some(x => x !== '')) rows.push(row); row = []; }
}
if (rows.length < 2) return [{ json: { error: 'The export has no rows. Check it is the bills report saved as CSV.' } }];
const head = rows[0], col = n => head.findIndex(h => h.toLowerCase() === String(n).toLowerCase());
const need = { job: cfg.field_job, vendor: cfg.field_vendor, ref: cfg.field_ref, date: cfg.field_date, amount: cfg.field_amount };
const missing = Object.values(need).filter(n => col(n) < 0);
if (missing.length) return [{ json: { error: `Column not found in the export: ${missing.join(', ')}. Columns are: ${head.join(', ')}. Set the field_* names in Config.` } }];
const since = Date.now() - Number(cfg.lookback_days || 60) * 864e5;
const num = v => Number(String(v).replace(/[^0-9.\-]/g, ''));
const bills = rows.slice(1).map(r => ({ job: r[col(need.job)], vendor: r[col(need.vendor)], ref: r[col(need.ref)],
  date: new Date(r[col(need.date)]).toISOString().slice(0, 10), amount: Math.round(num(r[col(need.amount)]) * 100) / 100 }))
  .filter(b => isFinite(b.amount) && new Date(b.date).getTime() >= since);
const exp = $('Find latest export').isExecuted ? $('Find latest export').first().json.files[0] : { name: src.export_name, modifiedTime: src.export_time };
return [{ json: { bills, export_name: exp.name, export_time: exp.modifiedTime } }];

// What QuickBooks returns for the same period: one bill missing, one amount typed wrong, one on the wrong job, one extra.
const d = n => new Date(Date.now() - n * 864e5).toISOString().slice(0, 10);
const bill = (doc, vendor, date, amt, job) => ({ DocNumber: doc, VendorRef: { name: vendor }, TxnDate: date, TotalAmt: amt,
  Line: [{ Amount: amt, AccountBasedExpenseLineDetail: { CustomerRef: { name: job } } }] });
return [{ json: { QueryResponse: { Bill: [
  bill('AL-5521', 'Acme Lumber', d(20), 4812.40, 'Maple St Remodel'),
  bill('BE-118', 'Brightline Electric', d(16), 2590.00, 'Maple St Remodel'),
  bill('AL-5530', 'Acme Lumber', d(15), 1180.00, 'Hill Rd Deck'),
  bill('PP-77', 'Precision Plumbing', d(13), 1625.00, 'Oak Ave Addition'),
  bill('AL-5544', 'Acme Lumber', d(8), 2210.75, 'Hill Rd Deck'),
  bill('GS-12', 'Granite Supply', d(7), 640.00, 'Oak Ave Addition'),
] } } }];

// Matches each Buildertrend bill to a QuickBooks bill: by bill number and vendor first, then by vendor, amount and a date
// within date_tolerance_days. Then compares totals per job. Problems seen in an earlier report are marked so new ones stand out.
const cfg = $('Config').first().json, src = $('Parse export').first().json;
const tol = Number(cfg.amount_tolerance || 0), dtol = Number(cfg.date_tolerance_days || 0) * 864e5, jtol = Number(cfg.job_total_tolerance || 0);
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const qb = ($json.QueryResponse && $json.QueryResponse.Bill || []).map(b => ({ ref: b.DocNumber || '', vendor: (b.VendorRef || {}).name || '',
  date: b.TxnDate, amount: Number(b.TotalAmt), job: ((b.Line || []).map(l => ((l.AccountBasedExpenseLineDetail || l.ItemBasedExpenseLineDetail || {}).CustomerRef || {}).name).find(Boolean)) || '' }));
const used = new Set(), issues = [];
for (const bt of src.bills) {
  let i = qb.findIndex((q, k) => !used.has(k) && bt.ref && norm(q.ref) === norm(bt.ref) && norm(q.vendor) === norm(bt.vendor));
  if (i < 0) i = qb.findIndex((q, k) => !used.has(k) && norm(q.vendor) === norm(bt.vendor) && Math.abs(q.amount - bt.amount) <= tol
    && Math.abs(new Date(q.date) - new Date(bt.date)) <= dtol);
  if (i < 0) { issues.push({ type: 'Missing in QuickBooks', job: bt.job, vendor: bt.vendor, ref: bt.ref, detail: `${bt.date}, ${bt.amount.toFixed(2)}` }); continue; }
  used.add(i); const q = qb[i];
  if (Math.abs(q.amount - bt.amount) > tol) issues.push({ type: 'Amount differs', job: bt.job, vendor: bt.vendor, ref: bt.ref,
    detail: `Buildertrend ${bt.amount.toFixed(2)}, QuickBooks ${q.amount.toFixed(2)}` });
  if (q.job && norm(q.job) !== norm(bt.job) && !norm(q.job).endsWith(norm(bt.job))) issues.push({ type: 'Different job', job: bt.job, vendor: bt.vendor, ref: bt.ref,
    detail: `QuickBooks has it on ${q.job}` });
}
const jobs = new Set(src.bills.map(b => b.job));
qb.forEach((q, k) => { if (!used.has(k) && (!q.job || [...jobs].some(j => norm(q.job).endsWith(norm(j))))) issues.push({ type: 'Missing in Buildertrend', job: q.job, vendor: q.vendor, ref: q.ref, detail: `${q.date}, ${q.amount.toFixed(2)}` }); });
const totals = [];
for (const j of jobs) {
  const a = src.bills.filter(b => b.job === j).reduce((s, b) => s + b.amount, 0);
  const b = qb.filter(q => norm(q.job).endsWith(norm(j))).reduce((s, q) => s + q.amount, 0);
  if (Math.abs(a - b) > jtol) totals.push({ job: j, buildertrend: a.toFixed(2), quickbooks: b.toFixed(2), diff: (b - a).toFixed(2) });
}
const sd = $getWorkflowStaticData('global'), seen = new Set(sd.seen || []);
const key = x => [x.type, x.job, x.vendor, x.ref].join('|');
issues.forEach(x => x.new = !seen.has(key(x)));
sd.seen = issues.map(key);
const age = (Date.now() - new Date(src.export_time)) / 36e5;
return [{ json: { issues, totals, checked: src.bills.length, qb_count: qb.length, export_name: src.export_name,
  stale: age > Number(cfg.max_export_age_hours || 36) ? Math.round(age) : 0, new_count: issues.filter(x => x.new).length } }];

// Plain-text email: a summary line, the export used, every problem grouped by type (new ones marked), then job totals.
const r = $json, out = [];
out.push(`${r.issues.length} bill problem${r.issues.length === 1 ? '' : 's'} (${r.new_count} new) and ${r.totals.length} job total${r.totals.length === 1 ? '' : 's'} out of step.`);
out.push(`Checked ${r.checked} Buildertrend bills from ${r.export_name} against ${r.qb_count} QuickBooks bills.`);
if (r.stale) out.push(`Warning: the export is ${r.stale} hours old. Export a fresh one so the check is current.`);
for (const t of ['Missing in QuickBooks', 'Amount differs', 'Different job', 'Missing in Buildertrend']) {
  const xs = r.issues.filter(x => x.type === t); if (!xs.length) continue;
  out.push('', `${t} (${xs.length})`);
  xs.forEach(x => out.push(`- ${x.new ? '[new] ' : ''}${x.job || '(no job)'}: ${x.vendor} ${x.ref || ''}, ${x.detail}`));
}
if (r.totals.length) { out.push('', 'Job totals that differ'); r.totals.forEach(t => out.push(`- ${t.job}: Buildertrend ${t.buildertrend}, QuickBooks ${t.quickbooks} (${t.diff})`)); }
if (!r.issues.length && !r.totals.length) out.push('', 'Everything matched.');
const n = r.issues.length + r.totals.length;
return [{ json: { subject: `${$('Config').first().json.workflow_label}: ${n ? n + ' to check' : 'all matched'}${r.stale ? ', export is ' + r.stale + 'h old' : ''}`, text: out.join('\n') } }];

// One alert for every failure path. $prevNode names the step that failed.
const cfg = $('Config').first().json;
return $input.all().map(i => {
  const e = i.json.error;
  const msg = String((typeof e === 'string' ? e : e && (e.description || e.message)) || i.json.message || JSON.stringify(i.json)).slice(0, 400);
  return { json: { text: `${cfg.workflow_label}: ${$prevNode.name} failed${i.json.ref ? ' for ' + i.json.ref : ''}. ${msg}` } };
});
